import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.GCMParameterSpec;
import java.io.*;
import java.net.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Arrays;
import java.util.Base64;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.logging.Logger;

public class SecureProxy {
    private static final Logger LOG = Logger.getLogger(SecureProxy.class.getName());
    private static final int BUFFER_POOL_SIZE = 32;
    private static final int BUFFER_CAPACITY = 8192;
    private static final int GCM_IV_LENGTH = 12;
    private static final int GCM_TAG_LENGTH_BITS = 128;

    private final ConcurrentLinkedQueue<ByteBuffer> bufferPool = new ConcurrentLinkedQueue<>();
    private final ConcurrentHashMap<String, SessionContext> activeSessions = new ConcurrentHashMap<>();
    private final byte[] masterKey;
    private final SecureRandom secureRandom = new SecureRandom();

    public SecureProxy(byte[] masterKey) {
        this.masterKey = Arrays.copyOf(masterKey, masterKey.length);
        for (int i = 0; i < BUFFER_POOL_SIZE; i++) {
            bufferPool.offer(ByteBuffer.allocate(BUFFER_CAPACITY));
        }
    }

    private static class SessionContext {
        final String sessionId;
        final byte[] sessionKey;
        final long createdAt;

        SessionContext(String sessionId, byte[] sessionKey) {
            this.sessionId = sessionId;
            this.sessionKey = sessionKey;
            this.createdAt = System.currentTimeMillis();
        }
    }

    private ByteBuffer acquireBuffer() {
        ByteBuffer buf = bufferPool.poll();
        if (buf == null) {
            buf = ByteBuffer.allocate(BUFFER_CAPACITY);
        }
        buf.clear();
        return buf;
    }

    private void releaseBuffer(ByteBuffer buf) {
        if (buf != null && buf.capacity() == BUFFER_CAPACITY) {
            // Zero out buffer contents before returning to pool
            buf.clear();
            byte[] zeros = new byte[buf.capacity()];
            buf.put(zeros);
            buf.clear();
            bufferPool.offer(buf);
        }
    }

    public byte[] encryptForStorage(byte[] plaintext, String sessionId) throws Exception {
        SessionContext ctx = activeSessions.get(sessionId);
        if (ctx == null) {
            throw new IllegalStateException("No active session: " + sessionId);
        }

        byte[] iv = new byte[GCM_IV_LENGTH];
        secureRandom.nextBytes(iv);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        SecretKeySpec keySpec = new SecretKeySpec(ctx.sessionKey, "AES");
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, new GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv));

        byte[] ciphertext = cipher.doFinal(plaintext);
        byte[] result = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(ciphertext, 0, result, iv.length, ciphertext.length);
        return result;
    }

    public String createSession(String clientId) {
        byte[] sessionKeyBytes = new byte[32];
        secureRandom.nextBytes(sessionKeyBytes);
        byte[] idBytes = new byte[16];
        secureRandom.nextBytes(idBytes);
        String sessionId = clientId + "-" + Base64.getUrlEncoder().withoutPadding().encodeToString(idBytes);
        SessionContext ctx = new SessionContext(sessionId, sessionKeyBytes);
        activeSessions.put(sessionId, ctx);
        return sessionId;
    }

    public void processProxyRequest(Socket clientSocket, String targetHost, int targetPort, String sessionId) throws Exception {
        SessionContext ctx = activeSessions.get(sessionId);
        if (ctx == null) {
            throw new SecurityException("Invalid session");
        }

        ByteBuffer processingBuffer = acquireBuffer();

        try (Socket targetSocket = new Socket(targetHost, targetPort);
             InputStream clientIn = clientSocket.getInputStream();
             OutputStream clientOut = clientSocket.getOutputStream();
             InputStream targetIn = targetSocket.getInputStream();
             OutputStream targetOut = targetSocket.getOutputStream()) {

            byte[] tempRead = new byte[4096];
            int bytesRead = clientIn.read(tempRead);

            if (bytesRead > 0) {
                byte[] clientData = Arrays.copyOf(tempRead, bytesRead);
                byte[] decryptedRequest = decryptClientData(clientData, ctx);

                processingBuffer.put(decryptedRequest);
                processingBuffer.flip();

                byte[] toForward = new byte[processingBuffer.remaining()];
                processingBuffer.get(toForward);

                targetOut.write(toForward);
                targetOut.flush();

                bytesRead = targetIn.read(tempRead);
                if (bytesRead > 0) {
                    byte[] response = Arrays.copyOf(tempRead, bytesRead);
                    byte[] encryptedResponse = encryptForStorage(response, sessionId);
                    clientOut.write(encryptedResponse);
                    clientOut.flush();
                }
            }
        } finally {
            releaseBuffer(processingBuffer);
        }
    }

    private byte[] decryptClientData(byte[] data, SessionContext ctx) throws Exception {
        if (data.length < GCM_IV_LENGTH) {
            throw new SecurityException("Invalid encrypted data");
        }

        byte[] iv = Arrays.copyOf(data, GCM_IV_LENGTH);
        byte[] ciphertext = Arrays.copyOfRange(data, GCM_IV_LENGTH, data.length);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        SecretKeySpec keySpec = new SecretKeySpec(ctx.sessionKey, "AES");
        cipher.init(Cipher.DECRYPT_MODE, keySpec, new GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv));

        return cipher.doFinal(ciphertext);
    }

    public void terminateSession(String sessionId) {
        SessionContext ctx = activeSessions.remove(sessionId);
        if (ctx != null) {
            Arrays.fill(ctx.sessionKey, (byte) 0);
        }
    }

    public int getPoolSize() {
        return bufferPool.size();
    }
}
